/**
 * Montana Forest Service rental cabins, lookouts and guard stations.
 *
 * The data in app/data/mt-cabins.json is generated by scripts/build-mt-cabins.mjs
 * from the USFS Recreation Opportunities layer and recreation.gov; every `bookUrl`
 * was checked against a live, bookable recreation.gov facility when it was built.
 */

export type CabinKind = "Cabin" | "Lookout" | "Guard station";

export type Cabin = {
  /** USFS recreation-area id, or the recreation.gov facility id for `src: "recreation.gov"` entries. */
  id: number;
  src: "usfs" | "recreation.gov";
  name: string;
  kind: CabinKind;
  /** Short forest name, e.g. "Custer Gallatin NF". */
  forest: string;
  /** "open" / "closed" as reported by the Forest Service, otherwise "unknown". */
  status: string;
  lat: number;
  lon: number;
  /** Verified recreation.gov booking page, or null when none could be verified. */
  bookUrl: string | null;
  /** Forest Service rental instructions, kept only when there is no verified link. */
  note: string;
};

export type CabinData = { generatedAt: string; sources: string[]; count: number; cabins: Cabin[] };

/** Recreation.gov's national reservation line, as printed in the Forest Service rental instructions. */
export const RESERVATION_PHONE = "1-877-444-6777";

/** Lowercase, drop apostrophes, and turn every other symbol into a single space. */
const norm = (s: string) => s.toLowerCase().normalize("NFKD").replace(/['’`]/g, "").replace(/[^a-z0-9]+/g, " ").trim();

/**
 * Find cabins by what a person would type: part of the name ("hogback", "anna creek",
 * "woods"), a kind ("lookout", "guard station"), or name plus forest ("garnet custer").
 *
 * Rules: every typed word must start some word in the cabin's name, kind or forest, and
 * at least one must start a word in the NAME itself. The second rule keeps a town search
 * like "Helena" from returning every cabin in the Helena-Lewis and Clark forest.
 * Best matches first; ties by name.
 */
export function searchCabins(cabins: Cabin[], query: string, limit = 6): Cabin[] {
  const q = norm(query);
  if (q.length < 2) return [];
  if (/^[\d\s.,+-]+$/.test(query.trim())) return []; // coordinates are handled by the caller
  const tokens = q.split(" ");
  const scored: Array<[number, Cabin]> = [];
  for (const cabin of cabins) {
    const name = norm(cabin.name);
    const nameWords = name.split(" ");
    const allWords = [...nameWords, ...norm(cabin.kind).split(" "), ...norm(cabin.forest).split(" ")];
    if (!tokens.every(t => allWords.some(w => w.startsWith(t)))) continue;
    if (!tokens.some(t => nameWords.some(w => w.startsWith(t)))) continue;
    let score = 40;
    if (name === q) score = 100;
    else if (name.startsWith(q)) score = 80;
    else if (tokens.every(t => nameWords.some(w => w.startsWith(t)))) score = 60;
    scored.push([score, cabin]);
  }
  scored.sort((a, b) => b[0] - a[0] || a[1].name.localeCompare(b[1].name));
  return scored.slice(0, limit).map(([, cabin]) => cabin);
}

/** One-line description used under a cabin's name in lists. */
export function cabinSubtitle(cabin: Cabin): string {
  return [cabin.kind, cabin.forest].filter(Boolean).join(" · ");
}
